"""Golden Hour - Evidence Scanner (Langflow custom component).

Checks the links and files inside a message with plain code (no AI):
  * unwraps short links (bit.ly and similar) to see the real destination
  * looks up when the destination domain was registered (RDAP)
  * flags look-alike brand names, IP addresses, odd characters, and APK files

Safety design:
  * The suspicious site itself is NEVER visited. The only servers contacted are
    well-known short-link services (a fixed allowlist) and the RDAP service.
  * A redirect is followed only if its next host is also on the allowlist.
  * Query strings and fragments are never sent anywhere and never printed.
  * Hosts are printed "defanged", for example example[.]com, so chat apps do not
    turn them into clickable links.
  * No result is ever a proof of safety. "No finding" does not mean "safe".
"""

import ipaddress
import json
import re
import socket
import time
import urllib.error
import urllib.parse
import urllib.request
from datetime import datetime, timezone

from langflow.custom import Component
from langflow.io import MessageTextInput, Output
from langflow.schema.message import Message

# ----------------------------------------------------------------- settings
MAX_URLS = 3
HTTP_TIMEOUT = 5  # seconds per request
MAX_HOPS = 4  # max short-link redirects to follow
TOTAL_BUDGET_SECONDS = 15  # all network work for one message
USER_AGENT = "GoldenHourEvidenceScanner/1.0 (scam safety check)"
RDAP_URL = "https://rdap.org/domain/"

# Only these hosts are ever contacted to unwrap a link.
SHORTENERS = {
    "bit.ly", "tinyurl.com", "t.co", "s.id", "is.gd", "cutt.ly", "rb.gy",
    "shorturl.at", "ow.ly", "buff.ly", "t.ly", "v.gd", "tiny.cc", "rebrand.ly",
}

# TLDs that make a "word.word" look like a real link. Keeps normal text such as
# "terima.kasih" or "Rp50.juta" from being treated as a domain.
KNOWN_TLDS = {
    "com", "net", "org", "id", "co", "io", "me", "xyz", "top", "icu", "click",
    "site", "online", "info", "biz", "vip", "shop", "store", "app", "link", "cc",
    "tv", "ly", "gl", "to", "is", "gd", "ink", "live", "fun", "club", "work",
    "cfd", "sbs", "cyou", "buzz", "tech", "space", "website", "pw", "ws", "in",
    "us", "uk", "sg", "my", "au", "jp", "cn", "ru", "de", "fr", "nl", "asia",
    "mobi", "pro", "dev", "page", "cloud", "digital", "today", "world", "life",
    "studio", "agency", "email", "support", "help", "bio", "gov", "edu", "mil",
    "int", "name", "tk", "ml", "ga", "cf", "gq", "su", "sh", "ai", "gg", "im",
    "ms", "nu", "fm", "am", "rest", "bond", "lol", "monster", "sbs",
}

# Cheap, open-to-anyone endings. Only an INFO note, never proof of a scam.
SUSPICIOUS_TLDS = {"xyz", "top", "icu", "click", "cfd", "sbs", "cyou", "buzz", "vip", "monster", "rest", "bond"}

TWO_LEVEL_SUFFIXES = {
    "co.id", "or.id", "web.id", "my.id", "sch.id", "ac.id", "go.id", "mil.id",
    "biz.id", "desa.id", "ponpes.id", "co.uk", "org.uk", "com.au", "com.sg",
    "co.jp", "com.my",
}

# Brand keyword -> official registrable domains.
# CHECK THIS LIST BEFORE THE DEMO. It is short on purpose and may be incomplete.
OFFICIAL_DOMAINS = {
    "bca": {"bca.co.id"},
    "bri": {"bri.co.id"},
    "bni": {"bni.co.id"},
    "mandiri": {"bankmandiri.co.id"},
    "telkomsel": {"telkomsel.com"},
    "telkom": {"telkom.co.id"},
    "tokopedia": {"tokopedia.com"},
    "shopee": {"shopee.co.id"},
    "lazada": {"lazada.co.id"},
    "dana": {"dana.id"},
    "ovo": {"ovo.id"},
    "gopay": {"gopay.co.id"},
    "ojk": {"ojk.go.id"},
    "polri": {"polri.go.id"},
    "bpjs": {"bpjs-kesehatan.go.id", "bpjsketenagakerjaan.go.id"},
    "pln": {"pln.co.id"},
    "jne": {"jne.co.id"},
    "sicepat": {"sicepat.com"},
}

_TLD_LIKE_TOKENS = KNOWN_TLDS | {"co", "or", "web", "my", "sch", "ac", "go"}
_SEVERITY_ORDER = {"TINGGI": 0, "SEDANG": 1, "INFO": 2}

_URL_RE = re.compile(
    r"""(?<![@\w.\-])
    (?:
        https?://(?:[^\s/@<>"'`]+@)?(?:[\w\-]+\.)+[a-z]{2,24}
      | https?://(?:[^\s/@<>"'`]+@)?(?:\d{1,3}\.){3}\d{1,3}
      | (?:[\w\-]+\.)+[a-z]{2,24}
    )
    (?::\d{2,5})?
    (?:/[^\s<>"'`]*)?""",
    re.IGNORECASE | re.VERBOSE,
)
_APK_RE = re.compile(r"(?<![\w/])([\w\-.]{1,60}\.apk)\b", re.IGNORECASE)
_TRAILING_PUNCT = ".,;:!?)]}'\""


# ------------------------------------------------------------ small helpers
def _now():
    return datetime.now(timezone.utc)


def defang(host):
    return host.replace(".", "[.]")


def _safe_text(value, limit=40):
    cleaned = re.sub(r"[^A-Za-z0-9\-_./]", "?", value)
    return cleaned[:limit] + ("..." if len(cleaned) > limit else "")


def registrable_domain(host):
    labels = host.split(".")
    if len(labels) <= 2:
        return host
    if ".".join(labels[-2:]) in TWO_LEVEL_SUFFIXES:
        return ".".join(labels[-3:])
    return ".".join(labels[-2:])


def _split_url(raw):
    url = raw if re.match(r"(?i)https?://", raw) else "https://" + raw
    try:
        parts = urllib.parse.urlsplit(url)
        host = (parts.hostname or "").lower().rstrip(".")
        _ = parts.port  # raises ValueError if the port is invalid
    except ValueError:
        return None
    if not host:
        return None
    return {"host": host, "path": parts.path or "", "has_userinfo": "@" in parts.netloc}


def _is_ip(host):
    try:
        ipaddress.ip_address(host)
        return True
    except ValueError:
        return False


def extract_targets(text):
    """Return (urls, apk_files). Both are lists of strings, without duplicates."""
    urls, seen = [], set()
    for match in _URL_RE.finditer(text):
        raw = match.group(0).rstrip(_TRAILING_PUNCT)
        info = _split_url(raw)
        if not info:
            continue
        host = info["host"]
        if not _is_ip(host) and host.rsplit(".", 1)[-1] not in KNOWN_TLDS:
            continue
        key = (host, info["path"])
        if key in seen:
            continue
        seen.add(key)
        urls.append(raw)

    apk_files = []
    for match in _APK_RE.finditer(text):
        name = match.group(1)
        if any(name.lower() in u.lower() for u in urls):
            continue  # already reported as part of a link
        if name not in apk_files:
            apk_files.append(name)
    return urls, apk_files


# ------------------------------------------------------------ network layer
def _resolve_ips(host):
    try:
        return sorted({info[4][0] for info in socket.getaddrinfo(host, None)})
    except OSError:
        return []


def is_public_host(host):
    """True only if the name resolves, and every address is a public one."""
    ips = _resolve_ips(host)
    if not ips:
        return False
    for ip in ips:
        try:
            addr = ipaddress.ip_address(ip)
        except ValueError:
            return False
        if addr.version == 6 and addr.ipv4_mapped:
            addr = addr.ipv4_mapped
        if not addr.is_global:
            return False
    return True


class _NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, req, fp, code, msg, headers, newurl):
        return None


def _fetch_location(url):
    """Ask a short-link service where a link goes. Never follows the redirect."""
    opener = urllib.request.build_opener(_NoRedirect)
    for method in ("HEAD", "GET"):
        request = urllib.request.Request(url, method=method, headers={"User-Agent": USER_AGENT})
        try:
            response = opener.open(request, timeout=HTTP_TIMEOUT)
            try:
                return response.headers.get("Location")
            finally:
                response.close()
        except urllib.error.HTTPError as error:
            location = error.headers.get("Location") if error.headers else None
            error.close()
            if location:
                return location
            if error.code in (405, 501) and method == "HEAD":
                continue
            return None
        except Exception:
            return None
    return None


def _parse_date(value):
    try:
        text = str(value).strip().replace("Z", "+00:00")
        text = re.sub(r"(\.\d{6})\d+", r"\1", text)
        parsed = datetime.fromisoformat(text)
        return parsed if parsed.tzinfo else parsed.replace(tzinfo=timezone.utc)
    except (ValueError, TypeError):
        return None


def parse_rdap_registration(data):
    if not isinstance(data, dict):
        return None
    for event in data.get("events", []) or []:
        if str(event.get("eventAction", "")).lower() == "registration":
            return _parse_date(event.get("eventDate"))
    return None


def _rdap_registration(domain):
    """Registration date of a domain, or None if it cannot be found."""
    if not re.fullmatch(r"[a-z0-9.\-]{3,253}", domain):
        return None
    request = urllib.request.Request(
        RDAP_URL + domain,
        headers={"User-Agent": USER_AGENT, "Accept": "application/rdap+json, application/json"},
    )
    try:
        with urllib.request.urlopen(request, timeout=HTTP_TIMEOUT) as response:
            data = json.loads(response.read(300_000).decode("utf-8", "replace"))
    except Exception:
        return None
    return parse_rdap_registration(data)


def unwrap_short_link(host, path, deadline):
    """Follow a chain of short links. Returns (host, path, status).

    status is one of: ok, blocked, unresolved, timeout, too_many.
    Only hosts on the SHORTENERS allowlist are ever contacted.
    """
    current_host, current_path = host, path
    for _ in range(MAX_HOPS):
        if current_host not in SHORTENERS:
            return current_host, current_path, "ok"
        if time.monotonic() > deadline:
            return None, None, "timeout"
        if not is_public_host(current_host):
            return None, None, "blocked"
        base = "https://" + current_host + current_path
        location = _fetch_location(base)
        if not location:
            return None, None, "unresolved"
        nxt = urllib.parse.urlsplit(urllib.parse.urljoin(base, location))
        if nxt.scheme not in ("http", "https") or not nxt.hostname:
            return None, None, "unresolved"
        current_host = nxt.hostname.lower().rstrip(".")
        current_path = nxt.path or ""
    if current_host in SHORTENERS:
        return None, None, "too_many"
    return current_host, current_path, "ok"


# ------------------------------------------------------------ the checks
def _age_text(days):
    if days < 1:
        return "kurang dari 1 hari"
    if days < 60:
        return f"{days} hari"
    if days < 365:
        return f"{days // 30} bulan"
    return f"{days // 365} tahun"


def find_brand_mismatch(host):
    """Return (keyword, official_domain) if the name imitates a brand, else None."""
    reg = registrable_domain(host)
    tokens = [t for t in re.split(r"[.\-]", host) if t and t not in _TLD_LIKE_TOKENS]
    name = "".join(tokens)
    best = None
    for keyword, officials in OFFICIAL_DOMAINS.items():
        hit = (keyword in tokens) if len(keyword) < 5 else (keyword in name)
        if not hit or reg in officials:
            continue
        if best is None or len(keyword) > len(best[0]):
            best = (keyword, sorted(officials)[0])
    return best


def check_target_host(host, path, deadline, findings):
    """Checks on the real destination host. Never contacts the host itself."""
    if _is_ip(host):
        findings.append(("SEDANG", "Alamat memakai angka IP, bukan nama situs. Situs resmi hampir selalu memakai nama."))
        return

    try:
        ascii_host = host.encode("idna").decode("ascii")
    except UnicodeError:
        ascii_host = host
    if "xn--" in ascii_host or any(ord(ch) > 127 for ch in host):
        findings.append(("TINGGI", "Nama situs memakai huruf khusus yang bisa menyamar sebagai situs lain."))
    host = ascii_host

    if path.lower().endswith(".apk"):
        findings.append(("TINGGI", "Tautan mengarah ke file APK, yaitu aplikasi Android yang dipasang di luar toko resmi."))

    tld = host.rsplit(".", 1)[-1]
    if tld in SUSPICIOUS_TLDS:
        findings.append(("INFO", f"Akhiran .{tld} murah dan terbuka untuk siapa saja. Ini bukan bukti sendiri, tapi perlu hati-hati."))

    mismatch = find_brand_mismatch(host)
    if mismatch:
        keyword, official = mismatch
        findings.append(("SEDANG", f"Nama situs memuat '{keyword}' tetapi bukan domain resmi ({official}). Bisa jadi menyamar."))

    reg = registrable_domain(host)
    created = None
    if time.monotonic() <= deadline:
        created = _rdap_registration(reg)
    if created is None:
        findings.append(("INFO", "Umur domain tidak diketahui (data pendaftaran tidak tersedia). Ini bukan tanda aman atau berbahaya."))
        return
    days = max((_now() - created).days, 0)
    when = created.strftime("%Y-%m-%d")
    if days <= 30:
        findings.append(("TINGGI", f"Domain tujuan baru didaftarkan {_age_text(days)} lalu (tanggal {when}). Lembaga resmi biasanya memakai domain yang sudah lama."))
    elif days <= 180:
        findings.append(("SEDANG", f"Domain tujuan didaftarkan {_age_text(days)} lalu (tanggal {when}), masih tergolong baru."))
    else:
        findings.append(("INFO", f"Domain tujuan berumur sekitar {_age_text(days)}. Umur domain yang lama tidak membuktikan situs itu asli."))


def analyze_url(raw, deadline):
    """Return (display_text, findings) for one link."""
    info = _split_url(raw)
    findings = []
    host, path = info["host"], info["path"]

    if info["has_userinfo"]:
        findings.append(("TINGGI", "Alamat memakai tanda @ untuk menyamarkan tujuan asli. Bagian sebelum @ bukan tujuan sebenarnya."))

    if host in SHORTENERS:
        display = defang(host) + _safe_text(path, 30)
        target_host, target_path, status = unwrap_short_link(host, path, deadline)
        if target_host is None:
            reasons = {
                "blocked": "layanan tidak bisa diperiksa dengan aman",
                "timeout": "waktu pemeriksaan habis",
                "too_many": "tautan berantai terlalu panjang",
                "unresolved": "tautan tidak ditemukan, diblokir, atau layanan tidak merespons",
            }
            findings.append(("SEDANG", f"Tautan pendek menyembunyikan tujuan, dan tujuannya tidak bisa diuraikan ({reasons[status]})."))
        else:
            findings.append(("SEDANG", f"Tautan pendek menyembunyikan tujuan asli. Tujuannya: {defang(_safe_text(target_host, 80))}"))
            check_target_host(target_host, target_path, deadline, findings)
    else:
        display = defang(_safe_text(host, 80))
        check_target_host(host, path, deadline, findings)

    findings.sort(key=lambda item: _SEVERITY_ORDER[item[0]])
    return display, findings


def build_report(text):
    text = text if isinstance(text, str) else str(getattr(text, "text", text) or "")
    deadline = time.monotonic() + TOTAL_BUDGET_SECONDS
    urls, apk_files = extract_targets(text)

    if not urls and not apk_files:
        return ("BUKTI TEKNIS: tidak ada tautan atau file yang dapat diperiksa dalam pesan ini. "
                "Ini bukan tanda bahwa pesan aman.")

    lines = ["BUKTI TEKNIS (diperiksa otomatis oleh kode, bukan oleh AI)"]
    for number, raw in enumerate(urls[:MAX_URLS], start=1):
        display, findings = analyze_url(raw, deadline)
        lines.append(f"Tautan {number}: {display}")
        lines.extend(f"- [{sev}] {msg}" for sev, msg in findings)
    if len(urls) > MAX_URLS:
        lines.append(f"Catatan: hanya {MAX_URLS} tautan pertama yang diperiksa.")

    for number, name in enumerate(apk_files[:MAX_URLS], start=1):
        lines.append(f"File {number}: {_safe_text(name, 40)}")
        lines.append("- [TINGGI] Pesan menyebut file APK. APK adalah aplikasi Android yang dipasang di luar toko resmi, "
                     "dan dapat dipakai untuk mencuri data atau kode OTP.")

    lines.append("Catatan: tidak adanya temuan bukan tanda bahwa pesan aman.")
    return "\n".join(lines)


